{
  "format_version": 3,
  "flavours": {
    "subject": {
      "id_prefix": "SUB-",
      "body": "required",
      "description": "Fixture subject",
      "use_when": [
        "Fixture root"
      ],
      "avoid_when": [],
      "distinguish_from": {},
      "fields": {
        "status": {
          "type": "enum",
          "values": [
            "draft",
            "accepted",
            "retired"
          ],
          "required": true
        }
      }
    },
    "support": {
      "id_prefix": "SUP-",
      "body": "required",
      "description": "Fixture support",
      "use_when": [
        "Fixture related item"
      ],
      "avoid_when": [],
      "distinguish_from": {},
      "fields": {
        "status": {
          "type": "enum",
          "values": [
            "draft",
            "accepted",
            "retired"
          ],
          "required": true
        },
        "amount": {
          "type": "integer"
        },
        "text": {
          "type": "string"
        },
        "flag": {
          "type": "boolean"
        }
      }
    }
  },
  "relations": {
    "supports": {
      "description": "Fixture support relation",
      "source": [
        "support"
      ],
      "target": [
        "subject"
      ],
      "inverse": "supported_by"
    }
  }
}

@prefix sh: <http://www.w3.org/ns/shacl#> .
<urn:fixture:policy:coverage> a sh:NodeShape ;
 sh:property <urn:fixture:policy:coverage-count> .
<urn:fixture:policy:coverage-count> a sh:PropertyShape ;
 sh:path <urn:mara:query:match> ;
 sh:qualifiedValueShape <urn:fixture:policy:accepted> ;
 sh:qualifiedMinCount 1 ; sh:qualifiedMaxCount 1 .
<urn:fixture:policy:accepted> a sh:NodeShape ;
 sh:property [ sh:path <urn:mara:query:column:lifecycle> ; sh:hasValue "accepted" ] .

[
  {
    "name": "supported_optional_absence",
    "definition_text": "{
  "format_version": 1,
  "id": "urn:fixture:query:supports",
  "columns": [
    "absent"
  ],
  "support_columns": [
    "edge"
  ],
  "select": "PREFIX r: <urn:mara:relation:>\nPREFIX f: <urn:mara:field:>\nPREFIX q: <urn:mara:query:>\nSELECT ?root ?absent ?edge WHERE {\n ?root ^r:supports ?support .\n ?edge q:source ?support ; q:target ?root ; q:relation r:supports .\n OPTIONAL { ?support f:status ?absent . FILTER(sameTerm(?absent, \"not-a-lifecycle\")) }\n}"
}",
    "shape_text": "@prefix sh: <http://www.w3.org/ns/shacl#> .
<urn:fixture:policy:coverage> a sh:NodeShape ;
 sh:property [ sh:path <urn:mara:query:match> ; sh:minCount 1 ] .
",
    "reject": false
  },
  {
    "name": "directional_terms",
    "definition_text": "{
  "format_version": 1,
  "id": "urn:fixture:query:supports",
  "columns": [
    "value"
  ],
  "support_columns": [],
  "select": "SELECT ?root ?value WHERE { VALUES ?value { \"text\"@en--ltr \"text\"@en--rtl } }"
}",
    "reject": true
  },
  {
    "name": "missing_root_signature",
    "definition_text": "{
  "format_version": 1,
  "id": "urn:fixture:query:supports",
  "columns": [
    "value"
  ],
  "support_columns": [],
  "select": "SELECT ?value WHERE { VALUES ?value { \"hello\" } }"
}",
    "reject": true
  },
  {
    "name": "missing_declared_signature",
    "definition_text": "{
  "format_version": 1,
  "id": "urn:fixture:query:supports",
  "columns": [
    "absent"
  ],
  "support_columns": [
    "edge"
  ],
  "select": "SELECT ?root ?value WHERE { VALUES ?value { \"hello\" } }"
}",
    "reject": true
  },
  {
    "name": "normalized_integer_facet",
    "definition_text": "{
  "format_version": 1,
  "id": "urn:fixture:query:supports",
  "columns": [
    "value"
  ],
  "support_columns": [],
  "select": "SELECT ?root ?value WHERE { VALUES ?value { \"1\"^^<http://www.w3.org/2001/XMLSchema#int> } }"
}",
    "reject": true
  },
  {
    "name": "normalized_integer_spelling",
    "definition_text": "{
  "format_version": 1,
  "id": "urn:fixture:query:supports",
  "columns": [
    "value"
  ],
  "support_columns": [],
  "select": "SELECT ?root ?value WHERE { VALUES ?value { \"01\"^^<http://www.w3.org/2001/XMLSchema#integer> } }"
}",
    "reject": true
  },
  {
    "name": "normalized_boolean_spelling",
    "definition_text": "{
  "format_version": 1,
  "id": "urn:fixture:query:supports",
  "columns": [
    "value"
  ],
  "support_columns": [],
  "select": "SELECT ?root ?value WHERE { VALUES ?value { \"1\"^^<http://www.w3.org/2001/XMLSchema#boolean> } }"
}",
    "reject": true
  },
  {
    "name": "normalized_double_spelling",
    "definition_text": "{
  "format_version": 1,
  "id": "urn:fixture:query:supports",
  "columns": [
    "value"
  ],
  "support_columns": [],
  "select": "SELECT ?root ?value WHERE { VALUES ?value { \"1.0\"^^<http://www.w3.org/2001/XMLSchema#double> } }"
}",
    "reject": true
  },
  {
    "name": "row_identity_collision",
    "definition_text": "{
  "format_version": 1,
  "id": "urn:fixture:query:supports",
  "columns": [
    "id",
    "flag"
  ],
  "support_columns": [],
  "select": "SELECT ?root ?id ?flag WHERE { VALUES (?id ?flag) { (<urn:mara:query:row:1> \"a\") (<urn:a> \"b\") } }"
}",
    "shape_text": "@prefix sh: <http://www.w3.org/ns/shacl#> .
<urn:fixture:policy:coverage> a sh:NodeShape ;
 sh:property [ sh:path ( <urn:mara:query:match> <urn:mara:query:column:id> <urn:mara:query:column:flag> ) ; sh:minCount 1 ] .
",
    "reject": false
  },
  {
    "name": "canonical_literal_identity",
    "definition_text": "{
  "format_version": 1,
  "id": "urn:fixture:query:supports",
  "columns": [
    "value"
  ],
  "support_columns": [],
  "select": "SELECT ?root ?value WHERE { VALUES ?value { \"1\" \"1\"^^<http://www.w3.org/2001/XMLSchema#integer> \"1\"^^<http://www.w3.org/2001/XMLSchema#double> true } }"
}",
    "shape_text": "@prefix sh: <http://www.w3.org/ns/shacl#> .
<urn:fixture:policy:coverage> a sh:NodeShape ; sh:property [ sh:path <urn:mara:query:match> ; sh:minCount 4 ] .
",
    "reject": false
  },
  {
    "name": "canonical_same_term",
    "definition_text": "{
  "format_version": 1,
  "id": "urn:fixture:query:supports",
  "columns": [
    "value"
  ],
  "support_columns": [],
  "select": "SELECT ?root ?value WHERE { VALUES ?value { \"1\" \"1\"^^<http://www.w3.org/2001/XMLSchema#integer> \"1\"^^<http://www.w3.org/2001/XMLSchema#double> true } FILTER(sameTerm(?value, \"1\"^^<http://www.w3.org/2001/XMLSchema#integer>)) }"
}",
    "shape_text": "@prefix sh: <http://www.w3.org/ns/shacl#> .
<urn:fixture:policy:coverage> a sh:NodeShape ; sh:property [ sh:path <urn:mara:query:match> ; sh:minCount 1 ] .
",
    "reject": false
  }
]
